import hashlib, json, os, pathlib, stat, sys
manifest_path=pathlib.Path(os.environ['STAMPED_DELIVERY_MANIFEST'])
receipt=json.load(open(os.environ['STAMPED_WORKER_STOP_RECEIPT']))
m=json.load(open(manifest_path)); root=manifest_path.parent
identity=hashlib.sha256(manifest_path.read_bytes()).hexdigest()
if identity != receipt['capture']['sha256']: raise SystemExit('manifest hash differs from worker receipt')
expected={'manifest.json','content','content/external'} | {row['path'] for row in m['entries']}
actual=set()
for base,dirs,files in os.walk(root,followlinks=False):
    for name in dirs+files: actual.add(str((pathlib.Path(base)/name).relative_to(root)))
extra=sorted(actual-expected); missing=sorted(expected-actual)
checked=0; failures=[]
for row in m['entries']:
    p=root/row['path']; st=p.lstat()
    if stat.S_IMODE(st.st_mode)!=row['mode']: failures.append([row['path'],'mode']); continue
    if row['kind']=='directory':
        if not stat.S_ISDIR(st.st_mode): failures.append([row['path'],'kind'])
    elif row['kind']=='symlink':
        if not stat.S_ISLNK(st.st_mode): failures.append([row['path'],'kind'])
        else:
            target=os.readlink(p); digest=hashlib.sha256(os.fsencode(target)).hexdigest()
            if target!=row['link_target'] or digest!=row['sha256']: failures.append([row['path'],'link'])
    elif row['kind']=='file':
        if not stat.S_ISREG(st.st_mode) or st.st_size!=row['size']: failures.append([row['path'],'kind-or-size']); continue
        h=hashlib.sha256()
        with p.open('rb') as f:
            for block in iter(lambda:f.read(1024*1024),b''): h.update(block)
        if h.hexdigest()!=row['sha256']: failures.append([row['path'],'sha256'])
    checked+=1
result={'manifest_sha256':identity,'receipt_sha256_match':True,'capture_status':m['capture_status'],'capture_entries':len(m['entries']),'entries_individually_checked':checked,'entry_failures':failures,'missing_entries':missing,'unmanifested_entries':extra,'complete_inventory_match':not extra and not missing and not failures,'reference_limits':json.load(open(pathlib.Path(os.environ['STAMPED_JUDGE_OUTPUT'])/'judge-target.json')).get('reference_limits')}
print(json.dumps(result,indent=2))
if failures or missing or extra: sys.exit(2)
